public sealed record ScoringPolicy(int PassMark, bool AllowLate, DateTimeOffset? ClosesAt);

public ScoringPolicy FreezeForSubmit(ScoringPolicy live, DateTimeOffset utc)
    => live with
    {
        AllowLate = false,
        ClosesAt = utc
    };

// live is unchanged; workers receive frozen.

public sealed record LtiConsumer(string Issuer, List<string> Audiences);

public LtiConsumer GrantAudience(LtiConsumer consumer, string audience)
    => consumer with
    {
        Audiences = [.. consumer.Audiences, audience]
    };
